def format_bytes(n):
    """Convert a byte size to a human-readable string like '1.5 KB' or '2.3 MB'."""
    if n < 0:
        raise ValueError("Size must be non-negative")
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024:
            return f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} PB"'
